 def brute(N,M,A,B,ints):
  bad=[False]*(N+1)
  for l,r in ints:
   for i in range(l,r+1):bad[i]=True
  reach=[False]*(N+1);reach[1]=True
  for x in range(1,N+1):
   if not reach[x]:continue
   for d in range(A,B+1):
    y=x+d
    if y>N:break
    if not bad[y]:reach[y]=True
  return 'Yes' if reach[N] else 'No'
